rootProject.name = "superbikeshed"



// Core library - Foundational types and utilities, no async dependencies.
include(":trikeshed-lib")

// Common utilities - Shared code and helpers, no async dependencies.
include(":trikeshed-common")

// IO abstractions - Interfaces and minimal async for input/output operations.
include(":trikeshed-io")

// Async modules - Implementations using Kotlin's Channel/Flow for concurrent operations.
include(":trikeshed-async-core") // Core async abstractions and primitives.
include(":trikeshed-reactor") // Core reactive programming model.
include(":trikeshed-net")     // Networking protocols (TCP, UDP, QUIC).
include(":trikeshed-quic")    // QUIC protocol implementation.
include(":trikeshed-torrent") // BitTorrent protocol implementation.
include(":trikeshed-dht")     // Distributed Hash Table implementation.
include(":trikeshed-ipc")     // Inter-process communication.
include(":trikeshed-ccek")    // Coroutine Context Element Key - orchestration framework.
include(":trikeshed-ljson")   // Large JSON parsing utilities.
include(":trikeshed-strace")  // System call tracing utilities.
include(":trikeshed-couchdb") // CouchDB integration.
include(":platform-launcher")
include(":trikeshed-ipfs")    // IPFS integration.
// include(":trikeshed-services") // Temporarily disabled due to plugin issues.
include(":trikeshed-cursor")  // Cursor-based data access.
include(":trikeshed-isam")    // Indexed Sequential Access Method implementation.
include(":trikeshed-lsmr")    // Log-Structured Merge-Tree implementation.
include(":trikeshed-uring")   // io_uring facade with CCEK orchestration.

// Channel-based protocol architecture
include(":trikeshed-channel-api")     // Protocol channelization API
include(":trikeshed-channel-impl")    // Protocol channel implementations
include(":trikeshed-channel-test")    // Protocol testing and recording

// Application modules
include(":rtsgame")      // Real-time strategy game example.

include(":boingDemo")    // Simple physics demo.
include(":fiduciary") // Patrick Devine Agent TDD implementation
include(":fiduciary-demo") // Standalone Fiduciary CouchDB Service Demo
include(":platform-launcher:hello-world-native") // Simple hello world native executable
include(":platform-launcher:ccek-main") // CCEK main executable

include(":k2script")      // Scripting engine.
// include(":kotlin-entity-scanner") // Has syntax errors - disabled temporarily.
include(":trikeshed-json") // JSON parsing and serialization.
// include(":kotlinx-serialization-wireproto") // Has syntax errors - disabled temporarily.
// include(":moneyfan") // Has syntax errors - disabled temporarily.
include(":trikeshed-sumo") // Simulation and modeling utilities.

include(":nexus") // Nexus service and dependency coordinate handling
include(":nexus:bootloader") // Standalone JVM bootloader for dependency resolution
// include(":nexus:intellij-plugin") // Temporarily disabled due to plugin conflict.
include(":SSH")           // SSH protocol implementation.
include(":spacegraph")    // Graph-based data visualization.
include(":ta4k")          // Technical analysis for trading.
